from pathlib import Path
from PIL import Image
from reportlab.pdfgen import canvas
from reportlab.lib.units import mm
from reportlab.pdfbase import pdfmetrics
from reportlab.pdfbase.ttfonts import TTFont
pdfmetrics.registerFont(TTFont('Chinese',r'C:\Windows\Fonts\msyh.ttc'))
out=Path('output/pdf/ArUco_150mm_ID0-3_打印版.pdf')
c=canvas.Canvas(str(out),pagesize=(210*mm,297*mm))
c.setTitle('PC构件测量 ArUco 150mm标准标志 ID0至3')
positions=['左上','右上','右下','左下']
for i in range(4):
 im=Image.open(f'outputs/markers/aruco_4x4_50_id{i}_150mm.png').convert('L')
 # Sample the standard 6x6 grid generated by OpenCV (4x4 code plus black border).
 bbox=im.point(lambda p:255 if p<128 else 0).getbbox()
 x0,y0,x1,y1=bbox;bits=[]
 for row in range(6):
  bits.append([im.getpixel((int(x0+(col+.5)*(x1-x0)/6),int(y0+(row+.5)*(y1-y0)/6)))<128 for col in range(6)])
 c.setFont('Chinese',16);c.drawString(20*mm,275*mm,f'ArUco 标志 {i}  ·  {positions[i]}')
 c.setFont('Chinese',10);c.drawString(20*mm,265*mm,'字典 DICT_4X4_50    黑色方块边长 150 mm')
 # Draw vector modules: exactly 25mm per cell; 6 cells = 150mm.
 left,bottom=30*mm,82*mm
 for row in range(6):
  for col in range(6):
   if bits[row][col]: c.rect(left+col*25*mm,bottom+(5-row)*25*mm,25*mm,25*mm,stroke=0,fill=1)
 c.setFont('Chinese',10)
 c.drawString(20*mm,61*mm,'打印：A4 纵向，实际大小 / 100%，关闭“适合页面”。')
 c.drawString(20*mm,53*mm,'打印后量黑色方块横、竖两边，均应为 150 mm。')
 c.drawString(20*mm,45*mm,'保留白边；保持本页朝向；标志与构件被测表面齐平。')
 c.drawString(20*mm,37*mm,'本页不确定现场标志间距；布置后仍需实测并记录。')
 c.setLineWidth(.5);c.line(55*mm,23*mm,155*mm,23*mm)
 c.line(55*mm,21*mm,55*mm,25*mm);c.line(155*mm,21*mm,155*mm,25*mm)
 c.setFont('Chinese',9);c.drawCentredString(105*mm,17*mm,'校验线 100 mm（只用于检查打印比例）')
 c.showPage()
c.save()
print(out.resolve())
import sys
sys.path.insert(0,str(Path('tmp/reader_deps').resolve()))
import pymupdf
pdf=pymupdf.open(out)
for i,page in enumerate(pdf):
 page.get_pixmap(matrix=pymupdf.Matrix(1.6,1.6)).save(f'tmp/pdfs/marker-page-{i+1}.png')
print('Rendered',len(pdf),'A4 pages')
